SELECT 'version du socle' AS controle, (SELECT value ->> 'version' FROM public.site_settings WHERE key = 'socle') AS valeur
UNION ALL SELECT 'membre reecrit un message', has_column_privilege('authenticated', 'public.messages', 'content', 'UPDATE')::text
UNION ALL SELECT 'membre modifie une conversation', has_table_privilege('authenticated', 'public.conversations', 'UPDATE')::text
UNION ALL SELECT 'colonne reserved_quantity', (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'shop_order_items' AND column_name = 'reserved_quantity')::text
UNION ALL SELECT 'fonctions de la 1.6.1', (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname IN ('shop_release_stock', 'shop_orders_release_stock', 'forum_author_name', 'guard_forum_topic_insert', 'guard_forum_reply_insert', 'guard_contact_message_insert', 'newsletter_known_source', 'newsletter_subscribe', 'guard_newsletter_subscriber_insert', 'ad_campaign_is_live', 'guard_ad_event_insert', 'promote_studio_admin', 'forum_category_counts', 'forum_topic_counts', 'forum_reply_like_counts', 'lms_course_learners', 'directory_departement_counts'))::text
UNION ALL SELECT 'reponse sous verrou du sujet', (SELECT count(*) FROM pg_proc WHERE proname = 'guard_forum_reply_insert' AND prosecdef AND prosrc LIKE '%FOR NO KEY UPDATE%')::text
UNION ALL SELECT 'visiteur s abonne en direct', has_table_privilege('anon', 'public.newsletter_subscribers', 'INSERT')::text
UNION ALL SELECT 'contraintes de la 1.6.1', (SELECT count(*) FROM pg_constraint WHERE conname IN ('shop_order_items_reserved_check', 'contact_messages_name_len', 'contact_messages_email_format', 'contact_messages_subject_len', 'contact_messages_message_len', 'newsletter_subscribers_email_format', 'newsletter_subscribers_first_name_len', 'newsletter_subscribers_source_len', 'ad_events_user_agent_len', 'ad_events_page_path_len', 'marketplace_listings_price_check', 'lms_courses_price_check', 'pricing_plans_price_check'))::text
UNION ALL SELECT 'contraintes non validees', (SELECT count(*) FROM pg_constraint WHERE NOT convalidated AND conname IN ('contact_messages_name_len', 'contact_messages_email_format', 'contact_messages_subject_len', 'contact_messages_message_len', 'newsletter_subscribers_email_format', 'newsletter_subscribers_first_name_len', 'newsletter_subscribers_source_len', 'ad_events_user_agent_len', 'ad_events_page_path_len', 'marketplace_listings_price_check', 'lms_courses_price_check', 'pricing_plans_price_check', 'pricing_plans_features_array'))::text
UNION ALL SELECT 'index de la 1.6.1', (SELECT count(*) FROM pg_indexes WHERE schemaname = 'public' AND indexname IN ('forum_likes_topic_idx', 'forum_likes_reply_idx', 'lms_enrollments_course_idx', 'contact_messages_created_at_idx', 'forum_replies_topic_created_idx', 'forum_replies_author_idx', 'forum_follows_topic_idx', 'forum_topics_category_idx', 'forum_topics_last_activity_idx', 'forum_topics_author_idx', 'blog_comments_post_created_idx', 'lms_progress_lesson_idx', 'payments_course_idx', 'crm_actions_prospect_idx', 'marketplace_listings_category_idx', 'marketplace_listings_departement_idx', 'geo_adjacency_neighbor_idx'))::text
UNION ALL SELECT 'index en double retire', (SELECT count(*) FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'geo_adjacency_place_idx')::text
UNION ALL SELECT 'plan directeur du socle', (SELECT count(*) FROM public.masterplan_sections WHERE title = 'Vision' AND content LIKE 'CDS est le socle commun%')::text
UNION ALL SELECT 'points renvoyant a V0.md', (SELECT count(*) FROM public.template_checks WHERE requirement LIKE '%V0.md%')::text
UNION ALL SELECT 'version 1.6.1 publiee', (SELECT count(*) FROM public.socle_versions WHERE version = '1.6.1' AND niveau = 'correctif')::text;
